import fs from 'node:fs';

const lines = fs.readFileSync('/tmp/probe.txt', 'utf8').split('\n').filter(Boolean);
const rows = [];
for (const line of lines) {
  const [code, out] = line.split('\t');
  if (out === 'INVALID') continue;
  const m = /(1,23[45](?:\.[0-9]+)?)$/.exec(out);
  if (!m) { console.error('PARSE FAIL', code, JSON.stringify(out)); process.exit(1); }
  const num = m[1];
  const sym = out.slice(0, out.length - num.length);
  const dot = num.indexOf('.');
  const digits = dot === -1 ? 0 : num.length - dot - 1;
  rows.push([code, sym, digits]);
}
rows.sort((a, b) => (a[0] < b[0] ? -1 : 1));

const esc = (s) => {
  let r = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '"') r += '\\"';
    else if (ch === '\\') r += '\\\\';
    else if (cp < 0x20 || cp > 0x7e) r += '\\u' + cp.toString(16).padStart(4, '0');
    else r += ch;
  }
  return r + '"';
};

const header = `/**
 * CLDR currency data for the \`en_US\` locale, captured from the reference
 * implementation (babel, as bundled with py-moneyed).
 *
 * Each entry maps an ISO 4217 code to \`[symbol, fractionDigits]\`:
 *   - \`symbol\`         string babel prefixes to the amount under en_US
 *   - \`fractionDigits\` decimals CLDR assigns to that currency
 *
 * A code missing from this table does not exist in py-moneyed either, and must
 * raise \`CurrencyDoesNotExist\`.
 */
export const CURRENCY_DATA = Object.freeze({
`;

const body = rows.map(([c, s, d]) => `  ${c}: [${esc(s)}, ${d}],`).join('\n');
fs.writeFileSync('/output/lib/currency_data.mjs', header + body + '\n});\n');
console.log('rows:', rows.length);
console.log('non-2 digits:', rows.filter((r) => r[2] !== 2).map((r) => `${r[0]}:${r[2]}`).join(' '));

