/**
 * Exceptions mirroring the Python side, so the entry point can reproduce the
 * interpreter's stderr line and exit status for each failure mode.
 */

/** Raised by `getCurrency()` for a code that py-moneyed does not know. */
export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.pythonName = 'moneyed.classes.CurrencyDoesNotExist';
  }
}

/**
 * Stands in for `decimal.InvalidOperation`, raised when comparing a NaN amount
 * and when a quantized result needs more digits than the decimal context's
 * precision (28) allows.
 */
export class InvalidOperation extends Error {
  constructor() {
    super("[<class 'decimal.InvalidOperation'>]");
    this.pythonName = 'decimal.InvalidOperation';
  }
}

/** Raised when two Money values of different currencies are compared. */
export class CurrencyMismatch extends Error {
  constructor(left, right) {
    super(`Cannot compare Money with different currencies: ${left} and ${right}`);
    this.pythonName = 'TypeError';
  }
}

/** Signals an argparse-style failure: usage + message on stderr, exit code 2. */
export class ArgumentParserError extends Error {
  constructor(message) {
    super(message);
    this.pythonName = 'ArgumentParserError';
  }
}

