/**
 * Python float semantics: `argparse(type=float)` parsing, plus the conversion
 * `Decimal(str(value))` that py-moneyed applies to a float amount.
 */

import { Decimal } from './decimal.mjs';

// Python's float() grammar, after underscore removal: an optional sign followed
// by digits with an optional fraction and exponent, or inf/infinity/nan.
const FLOAT_RE = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/;
const FLOAT_SPECIAL_RE = /^([+-]?)(inf|infinity|nan)$/i;

/**
 * Converts a command-line string to a double the way `float()` does.
 * Returns `null` when Python would raise ValueError.
 */
export function pythonFloat(text) {
  // float() tolerates surrounding whitespace and single underscores between
  // digits ("1_000.5"), but nothing else.
  const trimmed = text.trim();
  const bare = trimmed.replace(/(?<=[0-9])_(?=[0-9])/g, '');
  if (bare.includes('_') || bare === '') return null;

  const special = FLOAT_SPECIAL_RE.exec(bare);
  if (special) {
    if (special[2].toLowerCase() === 'nan') return NaN;
    return special[1] === '-' ? -Infinity : Infinity;
  }

  if (!FLOAT_RE.test(bare)) return null;
  return Number(bare);
}

/**
 * `str(float)` — the shortest round-tripping representation. V8 and CPython
 * agree on the digits; only the exponent threshold differs, which is immaterial
 * because the result is fed straight into a Decimal.
 */
export function floatToDecimalString(value) {
  if (Number.isNaN(value)) return 'NaN';
  if (value === Infinity) return 'Infinity';
  if (value === -Infinity) return '-Infinity';
  // String(-0) drops the sign that Python's repr keeps.
  if (Object.is(value, -0)) return '-0.0';
  return String(value);
}

/** `Decimal(str(float))`, as py-moneyed does when handed a float amount. */
export function floatToDecimal(value) {
  return Decimal.parse(floatToDecimalString(value));
}

