/**
 * The currency registry, mirroring `moneyed.get_currency()`.
 */

import { CURRENCY_DATA } from './currency_data.mjs';
import { CurrencyDoesNotExist } from './errors.mjs';

export class Currency {
  constructor(code, symbol, fractionDigits) {
    this.code = code;
    this.symbol = symbol;
    this.fractionDigits = fractionDigits;
  }

  toString() {
    return this.code;
  }
}

/**
 * Looks a currency up by ISO code, case-insensitively. Unknown codes raise
 * CurrencyDoesNotExist, quoting the upper-cased code like py-moneyed does.
 */
export function getCurrency(code) {
  const upper = String(code).toUpperCase();
  const entry = Object.prototype.hasOwnProperty.call(CURRENCY_DATA, upper)
    ? CURRENCY_DATA[upper]
    : null;
  if (!entry) throw new CurrencyDoesNotExist(upper);
  return new Currency(upper, entry[0], entry[1]);
}

