/**
 * Currency formatting for the `en_US` locale, reproducing what babel's
 * `format_currency()` does for the CLDR pattern `¤#,##0.00`:
 *
 *   - the currency symbol is a prefix, with the minus sign in front of it
 *   - the integer part is grouped in threes by ","
 *   - the fraction is fixed at the currency's CLDR digit count
 *   - rounding is ROUND_HALF_EVEN, on the exact decimal value
 *   - infinities render as the locale's infinity symbol instead of digits
 */

const GROUP_SEPARATOR = ',';
const DECIMAL_SEPARATOR = '.';
const MINUS_SIGN = '-';
const INFINITY_SYMBOL = '∞';
const GROUP_SIZE = 3;

/** Inserts the group separator every three digits from the right. */
function groupIntegerDigits(digits) {
  let out = '';
  for (let i = 0; i < digits.length; i += 1) {
    const fromRight = digits.length - i;
    if (i > 0 && fromRight % GROUP_SIZE === 0) out += GROUP_SEPARATOR;
    out += digits[i];
  }
  return out;
}

/**
 * Formats `amount` (a Decimal) as currency text.
 *
 * The sign is split off first — so negative zero keeps its minus, as in babel —
 * then the magnitude is quantized to the currency's digit count.
 */
export function formatCurrency(amount, currency) {
  const negative = amount.isSigned();

  let number;
  if (amount.isInfinite()) {
    number = INFINITY_SYMBOL;
  } else {
    const { integerDigits, fractionDigits } = amount.quantizeAbsolute(currency.fractionDigits);
    number = groupIntegerDigits(integerDigits);
    if (fractionDigits.length > 0) number += DECIMAL_SEPARATOR + fractionDigits;
  }

  return (negative ? MINUS_SIGN : '') + currency.symbol + number;
}

