/**
 * `moneyed.Money` — an amount plus a currency, formatted through the locale
 * machinery when stringified.
 */

import { getCurrency } from './currency.mjs';
import { Currency } from './currency.mjs';
import { CurrencyMismatch } from './errors.mjs';
import { Decimal } from './decimal.mjs';
import { floatToDecimal } from './pyfloat.mjs';
import { formatCurrency } from './format.mjs';

export class Money {
  /**
   * `amount` may be a JS number (converted like `Decimal(str(float))`), a
   * decimal literal string, or a Decimal; `currency` an ISO code or Currency.
   */
  constructor(amount, currency) {
    if (amount instanceof Decimal) {
      this.amount = amount;
    } else if (typeof amount === 'number') {
      this.amount = floatToDecimal(amount);
    } else {
      this.amount = Decimal.parse(String(amount));
    }
    this.currency = currency instanceof Currency ? currency : getCurrency(currency);
  }

  /** `self < other`; comparing across currencies is a TypeError in py-moneyed. */
  lessThan(other) {
    this.assertSameCurrency(other);
    return this.amount.compare(other.amount) < 0;
  }

  /** `self > other`. */
  greaterThan(other) {
    this.assertSameCurrency(other);
    return this.amount.compare(other.amount) > 0;
  }

  /** `self == other`. */
  equals(other) {
    return (
      this.currency.code === other.currency.code && this.amount.compare(other.amount) === 0
    );
  }

  assertSameCurrency(other) {
    if (this.currency.code !== other.currency.code) {
      throw new CurrencyMismatch(this.currency.code, other.currency.code);
    }
  }

  toString() {
    return formatCurrency(this.amount, this.currency);
  }
}

