/**
 * A small stand-in for Python's `argparse`, covering what this script needs:
 * required `--name value` options with a `type` converter, `-h/--help`, prefix
 * abbreviations, and byte-identical usage/error/help text.
 */

const HELP_INDENT = 2;
const MAX_HELP_POSITION = 24;
const USAGE_PREFIX = 'usage: ';

/**
 * `shutil.get_terminal_size().columns`: COLUMNS when it holds a positive
 * integer, otherwise the real terminal width, otherwise 80.
 */
function terminalColumns() {
  const env = process.env.COLUMNS;
  if (env !== undefined) {
    const columns = Number.parseInt(env, 10);
    if (Number.isInteger(columns) && columns > 0) return columns;
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) return process.stdout.columns;
  return 80;
}

/** Greedy word wrap, as textwrap does for the usage line and help text. */
function wrapWords(text, width, initialIndent, subsequentIndent) {
  const lines = [];
  let indent = initialIndent;
  let line = null;
  for (const word of text.split(/\s+/).filter(Boolean)) {
    if (line === null) {
      line = indent + word;
    } else if (line.length + 1 + word.length <= width) {
      line += ` ${word}`;
    } else {
      lines.push(line);
      indent = subsequentIndent;
      line = indent + word;
    }
  }
  if (line !== null) lines.push(line);
  return lines.length > 0 ? lines : [initialIndent.trimEnd()];
}

/** True for tokens argparse reads as an option rather than a value. */
function looksLikeOption(token) {
  if (token === '' || token[0] !== '-') return false;
  if (token.length === 1) return false; // a bare "-" is a value
  // A negative number is a value as long as no option looks like one.
  if (/^-\d+$|^-\d*\.\d+$/.test(token)) return false;
  return !token.includes(' ');
}

export class ArgumentError extends Error {
  constructor(message) {
    super(message);
    this.isArgumentError = true;
  }
}

/** Thrown for `-h`; the caller prints the help text and exits 0. */
export class HelpRequested extends Error {}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.actions = [
      {
        optionStrings: ['-h', '--help'],
        dest: 'help',
        isHelp: true,
        required: false,
        help: 'show this help message and exit',
      },
    ];
  }

  /** `add_argument('--name', type=..., required=...)`. */
  addArgument(optionString, { type = String, required = false, help = null } = {}) {
    const dest = optionString.replace(/^--?/, '').replace(/-/g, '_');
    this.actions.push({
      optionStrings: [optionString],
      dest,
      metavar: dest.toUpperCase(),
      type,
      required,
      help,
    });
    return this;
  }

  /** Longest option string wins; `--amo` style prefixes must be unambiguous. */
  findAction(name) {
    for (const action of this.actions) {
      if (action.optionStrings.includes(name)) return action;
    }
    const matches = [];
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) {
        if (optionString.startsWith(name)) matches.push({ action, optionString });
      }
    }
    if (matches.length === 1) return matches[0].action;
    if (matches.length > 1) {
      const names = matches.map((m) => m.optionString).join(', ');
      throw new ArgumentError(`ambiguous option: ${name} could match ${names}`);
    }
    return null;
  }

  /**
   * Parses `argv`, returning the namespace object. Throws ArgumentError for any
   * usage problem and HelpRequested for `-h`.
   */
  parseArgs(argv) {
    const namespace = {};
    const extras = [];
    const seen = new Set();
    let onlyPositionals = false;

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];

      if (onlyPositionals || !looksLikeOption(token)) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        onlyPositionals = true;
        continue;
      }

      const equals = token.indexOf('=');
      const name = equals === -1 ? token : token.slice(0, equals);
      const action = this.findAction(name);
      if (action === null) {
        extras.push(token);
        continue;
      }
      if (action.isHelp) throw new HelpRequested();

      let value;
      if (equals !== -1) {
        value = token.slice(equals + 1);
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          throw new ArgumentError(`argument ${action.optionStrings.join('/')}: expected one argument`);
        }
        value = next;
        i += 1;
      }

      namespace[action.dest] = this.convert(action, value);
      seen.add(action.dest);
    }

    const missing = this.actions.filter((a) => a.required && !seen.has(a.dest));
    if (missing.length > 0) {
      const names = missing.map((a) => a.optionStrings.join('/')).join(', ');
      throw new ArgumentError(`the following arguments are required: ${names}`);
    }
    if (extras.length > 0) {
      throw new ArgumentError(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /** Runs the action's `type` callable, reporting failures like argparse. */
  convert(action, value) {
    const converted = action.type(value);
    if (converted === null || converted === undefined) {
      throw new ArgumentError(
        `argument ${action.optionStrings.join('/')}: invalid ${action.type.typeName} value: '${value}'`,
      );
    }
    return converted;
  }

  /** The `usage: ...` block, word-wrapped exactly as argparse wraps it. */
  formatUsage() {
    const width = Math.max(terminalColumns() - 2, 11);
    const parts = this.actions.map((action) => {
      const invocation = action.isHelp
        ? `[${action.optionStrings[0]}]`
        : `${action.optionStrings[0]} ${action.metavar}`;
      return action.required || action.isHelp ? invocation : `[${invocation}]`;
    });
    const text = [this.prog, ...parts].join(' ');
    const indent = ' '.repeat(USAGE_PREFIX.length + this.prog.length + 1);
    return `${wrapWords(text, width, USAGE_PREFIX, indent).join('\n')}\n`;
  }

  /** The full `-h` output: usage, then the options section. */
  formatHelp() {
    const width = Math.max(terminalColumns() - 2, 11);
    const invocations = this.actions.map((action) =>
      action.isHelp
        ? action.optionStrings.join(', ')
        : `${action.optionStrings[0]} ${action.metavar}`,
    );
    const actionMaxLength = Math.max(...invocations.map((s) => s.length)) + HELP_INDENT;
    const maxHelpPosition = Math.min(MAX_HELP_POSITION, Math.max(width - 20, HELP_INDENT * 2));
    const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);
    const helpWidth = Math.max(width - helpPosition, 11);

    const lines = [this.formatUsage(), '\noptions:\n'];
    this.actions.forEach((action, index) => {
      const invocation = ' '.repeat(HELP_INDENT) + invocations[index];
      if (!action.help) {
        lines.push(`${invocation}\n`);
        return;
      }
      const indent = ' '.repeat(helpPosition);
      const helpLines = wrapWords(action.help, helpWidth, '', '');
      if (invocation.length <= helpPosition - 2) {
        lines.push(`${invocation.padEnd(helpPosition)}${helpLines[0]}\n`);
      } else {
        lines.push(`${invocation}\n${indent}${helpLines[0]}\n`);
      }
      for (const extra of helpLines.slice(1)) lines.push(`${indent}${extra}\n`);
    });
    return lines.join('');
  }

  /** `parser.error()`: usage + message on stderr, exit status 2. */
  exitWithError(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }
}

