/**
 * Port of test19.py: build two Money values in the same currency and print the
 * smaller one.
 */

import { ArgumentError, ArgumentParser, HelpRequested } from './lib/argparse.mjs';
import { floatType, strType } from './lib/types.mjs';
import { Money } from './lib/money.mjs';

// argparse derives prog from basename(sys.argv[0]); for the reference build that
// is 'test19_executable', and the usage/help text has to match it.
const PROG = 'test19_executable';

const parser = new ArgumentParser(PROG);
parser.addArgument('--amount1', { type: floatType, required: true });
parser.addArgument('--amount2', { type: floatType, required: true });
parser.addArgument('--currency', { type: strType, required: true });

let args;
try {
  args = parser.parseArgs(process.argv.slice(2));
} catch (error) {
  if (error instanceof HelpRequested) {
    process.stdout.write(parser.formatHelp());
    process.exit(0);
  }
  if (error instanceof ArgumentError) parser.exitWithError(error.message);
  throw error;
}

try {
  // 创建两个Money对象
  const m1 = new Money(args.amount1, args.currency);
  const m2 = new Money(args.amount2, args.currency);
  // 选择较小者
  let smaller;
  if (m1.lessThan(m2)) {
    smaller = m1;
  } else {
    smaller = m2;
  }
  // 打印较小者的Money对象
  console.log(String(smaller));
} catch (error) {
  // An uncaught Python exception prints a traceback on stderr and exits 1.
  if (error.pythonName) {
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write(`${error.pythonName}: ${error.message}\n`);
    process.exit(1);
  }
  throw error;
}

