/**
 * Differential harness: runs the reference executable and the Node port with the
 * same argv, comparing stdout, stderr and exit status byte for byte.
 *
 *   node /output/tools/difftest.mjs [--stderr]
 */

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';

const REF = '/workspace/dataset/test19_executable';
const PORT = '/output/test19.mjs';
const compareStderr = process.argv.includes('--stderr');

function run(cmd, argv) {
  const r = spawnSync(cmd[0], [...cmd.slice(1), ...argv], {
    env: { ...process.env, LC_ALL: 'en_US.UTF-8', COLUMNS: process.env.COLUMNS ?? '80' },
    encoding: 'utf8',
  });
  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status };
}

const cases = [];
const add = (...argv) => cases.push(argv);

// Sample cases from the task statement.
add('--amount1', '190.22', '--amount2', '53.46', '--currency', 'EUR');
add('--amount1', '983.9', '--amount2', '567.06', '--currency', 'GBP');
add('--amount1', '197.25', '--amount2', '630.55', '--currency', 'EUR');
add('--amount1', '204.37', '--amount2', '883.69', '--currency', 'CAD');

// Every known currency code, in both orderings.
const codes = fs
  .readFileSync('/output/lib/currency_data.mjs', 'utf8')
  .split('\n')
  .map((l) => /^ {2}([A-Z]{3}):/.exec(l))
  .filter(Boolean)
  .map((m) => m[1]);
for (const code of codes) {
  add('--amount1', '1234.5678', '--amount2', '87.005', '--currency', code);
  add('--amount1', '-9876.545', '--amount2', '-9876.555', '--currency', code);
}

// Rounding, sign, magnitude and parsing edge cases.
const amounts = [
  '0', '-0.0', '0.005', '0.015', '0.025', '2.675', '1234.5', '1235.5', '.5', '1.',
  '1e5', '1e-7', '1_000.5', '+3.25', '  2.5  ', '0.1', '0.2', '-0.001', '99999.999',
  '1e21', '1e25', '1e26', '1e30', '12345678901234567890.5', '1234567890123456789',
  '0.0000001', '123456.789', '-1e-9', '9.995', '10.005', '1e15', '1e16', '1e17',
];
for (const a of amounts) {
  for (const b of ['1', '1e9', '-5', a]) {
    for (const c of ['USD', 'JPY', 'BHD', 'CLF', 'XOF', 'XXX']) add('--amount1', a, '--amount2', b, '--currency', c);
  }
}

// Argument-parsing behaviour.
add('--amount1=5', '--amount2=6', '--currency=USD');
add('--curr', 'USD', '--amount1', '5', '--amount2', '6');
add('--amo', '1', '--amount2', '2', '--currency', 'USD');
add('--amount1', '5', '--amount2', '6', '--currency', 'USD', '--amount1', '9');
add('--', '--amount1', '5', '--amount2', '6', '--currency', 'USD');
add('--amount1', '5', '--amount2', '6', '--currency', 'USD', 'extra');
add('--amount1', '5', '--amount2', '-6.5', '--currency', 'USD');
add('--amount1', '5');
add('--amount2', '5');
add();
add('-h');
add('--help');
add('--amount1', 'abc', '--amount2', '2', '--currency', 'USD');
add('--amount1', '1', '--amount2', 'x1', '--currency', 'USD');
add('--amount1', '1', '--amount2', '2', '--currency', 'ZZZ');
add('--amount1', '1', '--amount2', '2', '--currency', 'usd');
add('--amount1', '1', '--amount2', '2', '--currency', '');
add('--amount1', '1', '--amount2', '2');
add('--amount1', '1', '--amount2', '2', '--currency');
add('--amount1', '-inf', '--amount2', '0', '--currency', 'USD');
add('--amount1=-inf', '--amount2=0', '--currency=USD');
add('--amount1=inf', '--amount2=inf', '--currency=USD');
add('--amount1=nan', '--amount2=0', '--currency=USD');
add('--amount1=1_0', '--amount2=1__0', '--currency=USD');
add('--amount1=0x10', '--amount2=2', '--currency=USD');
add('--foo', '1', '--amount1', '1', '--amount2', '2', '--currency', 'USD');
add('-x', '--amount1', '1', '--amount2', '2', '--currency', 'USD');

// Randomised amounts across a sample of currencies.
let seed = 12345;
const rand = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648);
const sample = ['USD', 'EUR', 'GBP', 'JPY', 'CAD', 'AUD', 'CHF', 'INR', 'KWD', 'CLF', 'ISK', 'VND'];
for (let i = 0; i < 300; i += 1) {
  const scale = [1, 100, 10000, 1e7, 1e-3][i % 5];
  const a = ((rand() - 0.35) * scale).toString();
  const b = ((rand() - 0.35) * scale).toString();
  add('--amount1', a, '--amount2', b, '--currency', sample[i % sample.length]);
}

let failures = 0;
for (const argv of cases) {
  const ref = run([REF], argv);
  const port = run(['node', PORT], argv);
  const same =
    ref.out === port.out && ref.code === port.code && (!compareStderr || ref.err === port.err);
  if (!same) {
    failures += 1;
    console.log('FAIL', JSON.stringify(argv));
    console.log('  ref :', JSON.stringify(ref.out), 'rc=' + ref.code);
    console.log('  port:', JSON.stringify(port.out), 'rc=' + port.code);
    if (compareStderr && ref.err !== port.err) {
      console.log('  ref  stderr:', JSON.stringify(ref.err.split('\n').slice(-3).join('\n')));
      console.log('  port stderr:', JSON.stringify(port.err));
    }
  }
}
console.log(`${cases.length - failures}/${cases.length} cases match`);
process.exit(failures === 0 ? 0 : 1);

