import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test19_executable';
const PORT = '/output/test19.mjs';

function run(cmd, argv, columns) {
  const env = { ...process.env, LC_ALL: 'en_US.UTF-8' };
  if (columns === null) delete env.COLUMNS;
  else env.COLUMNS = String(columns);
  const r = spawnSync(cmd[0], [...cmd.slice(1), ...argv], { env, encoding: 'utf8' });
  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status };
}

const cases = [
  ['--amount1', '1'],
  ['--amount2', '5'],
  [],
  ['-h'],
  ['--help'],
  ['--amount1', 'abc', '--amount2', '2', '--currency', 'USD'],
  ['--amount1', '1', '--amount2', 'x1', '--currency', 'USD'],
  ['--amo', '1', '--amount2', '2', '--currency', 'USD'],
  ['--amount1', '5', '--amount2', '6', '--currency', 'USD', 'extra'],
  ['--', '--amount1', '5', '--amount2', '6', '--currency', 'USD'],
  ['--amount1', '1', '--amount2', '2', '--currency'],
  ['--amount1', '-inf', '--amount2', '0', '--currency', 'USD'],
  ['--foo', '1', '--amount1', '1', '--amount2', '2', '--currency', 'USD'],
  ['--amount1=0x10', '--amount2=2', '--currency=USD'],
];

let failures = 0;
for (const columns of [null, 40, 60, 78, 79, 80, 85, 100, 200]) {
  for (const argv of cases) {
    const ref = run([REF], argv, columns);
    const port = run(['node', PORT], argv, columns);
    if (ref.out !== port.out || ref.err !== port.err || ref.code !== port.code) {
      failures += 1;
      console.log(`FAIL COLUMNS=${columns}`, JSON.stringify(argv));
      console.log('  ref :', JSON.stringify(ref.out), JSON.stringify(ref.err), ref.code);
      console.log('  port:', JSON.stringify(port.out), JSON.stringify(port.err), port.code);
    }
  }
}
console.log(failures === 0 ? 'all stderr/stdout matches' : `${failures} failures`);

