/**
 * Fuzz pass focused on float repr fidelity and half-even ties: long decimal
 * literals, exponent notation, and values sitting exactly on a rounding tie.
 */

import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test19_executable';
const PORT = '/output/test19.mjs';

function run(cmd, argv) {
  const r = spawnSync(cmd[0], [...cmd.slice(1), ...argv], {
    env: { ...process.env, LC_ALL: 'en_US.UTF-8', COLUMNS: '80' },
    encoding: 'utf8',
  });
  return { out: r.stdout ?? '', code: r.status };
}

let seed = 987654321;
const rand = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648);

const currencies = ['USD', 'JPY', 'BHD', 'CLF', 'EUR', 'GBP', 'ISK', 'TND', 'UYW'];
const values = [];

// Long, high-precision literals.
for (let i = 0; i < 60; i += 1) {
  const digits = 1 + Math.floor(rand() * 20);
  let s = rand() < 0.5 ? '-' : '';
  s += String(1 + Math.floor(rand() * 9));
  for (let d = 0; d < digits; d += 1) s += String(Math.floor(rand() * 10));
  s += `.${String(Math.floor(rand() * 1e9)).padStart(9, '0')}`;
  values.push(s);
}
// Exponent notation across the representable range.
for (let i = 0; i < 40; i += 1) {
  const exp = Math.floor(rand() * 50) - 25;
  values.push(`${(rand() * 9.99).toFixed(1 + Math.floor(rand() * 15))}e${exp}`);
}
// Exact rounding ties for 0-, 2-, 3- and 4-digit currencies.
for (let i = 0; i < 40; i += 1) {
  const whole = Math.floor(rand() * 1000);
  values.push(`${whole}.5`, `${whole}.005`, `${whole}.0005`, `${whole}.00005`);
  values.push(`-${whole}.5`, `-${whole}.125`, `-${whole}.375`);
}

let failures = 0;
let checked = 0;
for (let i = 0; i < values.length; i += 1) {
  const argv = [
    '--amount1', values[i],
    '--amount2', values[(i * 7 + 3) % values.length],
    '--currency', currencies[i % currencies.length],
  ];
  const ref = run([REF], argv);
  const port = run(['node', PORT], argv);
  checked += 1;
  if (ref.out !== port.out || ref.code !== port.code) {
    failures += 1;
    console.log('FAIL', JSON.stringify(argv));
    console.log('  ref :', JSON.stringify(ref.out), ref.code);
    console.log('  port:', JSON.stringify(port.out), port.code);
  }
}
console.log(`${checked - failures}/${checked} fuzz cases match`);
process.exit(failures === 0 ? 0 : 1);

