/**
 * Exact decimal values, implemented with digit strings so that arbitrary
 * magnitudes round exactly like Python's `decimal.Decimal` (and without
 * touching BigInt).
 *
 * A value is `sign * coefficient * 10 ** exponent`, where `coefficient` is a
 * digit string with no leading zeros ("0" for zero). Infinity and NaN are
 * tracked with the `special` flag, as `Decimal("Infinity")` / `Decimal("NaN")`
 * do on the Python side.
 */

import { InvalidOperation } from './errors.mjs';

/** Precision of Python's default decimal context. */
export const CONTEXT_PRECISION = 28;

const NUMERIC_RE = /^([+-]?)(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/;
const SPECIAL_RE = /^([+-]?)(inf|infinity|nan)$/i;

export class Decimal {
  constructor(negative, coefficient, exponent, special = null) {
    this.negative = negative;
    this.coefficient = coefficient;
    this.exponent = exponent;
    this.special = special; // null | 'inf' | 'nan'
  }

  /**
   * Parses a decimal literal the way `Decimal(str)` does: optional sign,
   * digits with an optional fraction, optional exponent, or inf/nan.
   */
  static parse(text) {
    const special = SPECIAL_RE.exec(text);
    if (special) {
      const kind = special[2].toLowerCase() === 'nan' ? 'nan' : 'inf';
      return new Decimal(special[1] === '-', '0', 0, kind);
    }

    const m = NUMERIC_RE.exec(text);
    const intPart = m ? m[2] : '';
    const fracPart = m && m[3] !== undefined ? m[3] : '';
    if (!m || intPart.length + fracPart.length === 0) {
      throw new Error(`invalid decimal literal: ${text}`);
    }

    const exponent = (m[4] !== undefined ? parseInt(m[4], 10) : 0) - fracPart.length;
    const digits = stripLeadingZeros(intPart + fracPart);
    return new Decimal(m[1] === '-', digits, exponent);
  }

  isNaN() {
    return this.special === 'nan';
  }

  isInfinite() {
    return this.special === 'inf';
  }

  isZero() {
    return this.special === null && this.coefficient === '0';
  }

  /** True for negative values *and* for negative zero, like `is_signed()`. */
  isSigned() {
    return this.negative;
  }

  abs() {
    return new Decimal(false, this.coefficient, this.exponent, this.special);
  }

  /**
   * Three-way comparison. NaN operands raise InvalidOperation, matching a
   * Python `<` against `Decimal("NaN")`.
   */
  compare(other) {
    if (this.isNaN() || other.isNaN()) throw new InvalidOperation();

    const leftSign = signOf(this);
    const rightSign = signOf(other);
    if (leftSign !== rightSign) return leftSign < rightSign ? -1 : 1;
    if (leftSign === 0) return 0; // both zero, sign of zero is irrelevant

    const magnitude = compareMagnitude(this, other);
    return leftSign > 0 ? magnitude : -magnitude;
  }

  /**
   * Rounds to `places` decimals with ROUND_HALF_EVEN and returns the absolute
   * value split into `{ integerDigits, fractionDigits }` digit strings.
   *
   * Raises InvalidOperation when the quantized coefficient would exceed the
   * context precision, exactly as `Decimal.quantize()` does.
   */
  quantizeAbsolute(places) {
    let { integerDigits, fractionDigits } = this.abs().toPlainDigits();

    if (fractionDigits.length <= places) {
      fractionDigits += '0'.repeat(places - fractionDigits.length);
    } else {
      const kept = fractionDigits.slice(0, places);
      const dropped = fractionDigits.slice(places);
      const rounded = roundHalfEven(integerDigits + kept, dropped);
      integerDigits = places === 0 ? rounded : rounded.slice(0, rounded.length - places);
      fractionDigits = places === 0 ? '' : rounded.slice(rounded.length - places);
    }

    integerDigits = stripLeadingZeros(integerDigits);
    const significant = stripLeadingZeros(integerDigits + fractionDigits);
    if (significant.length > CONTEXT_PRECISION) throw new InvalidOperation();

    return { integerDigits, fractionDigits };
  }

  /** Expands the value to plain (non-exponential) integer/fraction digits. */
  toPlainDigits() {
    const digits = this.coefficient;
    if (this.exponent >= 0) {
      return { integerDigits: digits + '0'.repeat(this.exponent), fractionDigits: '' };
    }
    const shift = -this.exponent;
    if (digits.length > shift) {
      return {
        integerDigits: digits.slice(0, digits.length - shift),
        fractionDigits: digits.slice(digits.length - shift),
      };
    }
    return {
      integerDigits: '0',
      fractionDigits: '0'.repeat(shift - digits.length) + digits,
    };
  }
}

/** -1, 0 or 1; zero (including negative zero) always compares as 0. */
function signOf(value) {
  if (value.isZero()) return 0;
  return value.negative ? -1 : 1;
}

/** Compares |a| and |b|, both non-zero, honouring infinities. */
function compareMagnitude(a, b) {
  if (a.isInfinite() || b.isInfinite()) {
    if (a.isInfinite() && b.isInfinite()) return 0;
    return a.isInfinite() ? 1 : -1;
  }

  const aScale = a.coefficient.length + a.exponent;
  const bScale = b.coefficient.length + b.exponent;
  if (aScale !== bScale) return aScale < bScale ? -1 : 1;

  const width = Math.max(a.coefficient.length, b.coefficient.length);
  const aDigits = a.coefficient.padEnd(width, '0');
  const bDigits = b.coefficient.padEnd(width, '0');
  if (aDigits === bDigits) return 0;
  return aDigits < bDigits ? -1 : 1;
}

/**
 * Applies ROUND_HALF_EVEN: `kept` is the digit string being retained and
 * `dropped` everything cut off. Returns `kept` incremented when required, one
 * digit longer if the carry ripples off the front.
 */
function roundHalfEven(kept, dropped) {
  const first = dropped.charAt(0);
  let roundUp;
  if (first > '5') {
    roundUp = true;
  } else if (first < '5') {
    roundUp = false;
  } else if (/[1-9]/.test(dropped.slice(1))) {
    roundUp = true; // strictly greater than a half
  } else {
    roundUp = (kept.charCodeAt(kept.length - 1) - 48) % 2 === 1; // tie: to even
  }
  return roundUp ? incrementDigits(kept) : kept;
}

/** Adds one to a non-negative digit string. */
function incrementDigits(digits) {
  const out = digits.split('');
  let i = out.length - 1;
  while (i >= 0) {
    if (out[i] === '9') {
      out[i] = '0';
      i -= 1;
    } else {
      out[i] = String.fromCharCode(out[i].charCodeAt(0) + 1);
      return out.join('');
    }
  }
  return `1${out.join('')}`;
}

function stripLeadingZeros(digits) {
  const trimmed = digits.replace(/^0+/, '');
  return trimmed === '' ? '0' : trimmed;
}
